arguments.command:
cd /tmp/sv-0b0e5c73a8b04928aa25bba3c8ddf239/symbols && \
# Use dynamic symbols to find function names for each PC offset
# libmonosgen-2.0.so frames: 0x222098, 0x222234, 0x19bac0, 0x19bc14
# libSystem.Native.so frames: 0x8f14, 0x12a48

# For libmonosgen-2.0.so - find nearest symbol below each address
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
    echo -n "  $addr -> "
    nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | awk -v target="$addr" '
    BEGIN { best_addr=0; best_name="" }
    {
        addr = strtonum("0x" $1)
        tgt = strtonum(target)
        if (addr <= tgt && addr > best_addr) {
            best_addr = addr
            best_name = $3
        }
    }
    END { printf "%s+0x%x\n", best_name, strtonum(target) - best_addr }
    '
done

